{"command":"python - <<'PY'
from celery import Celery
from celery.exceptions import AlreadyRegistered
app=Celery('repro', broker='memory://', backend='cache+memory://')
def factory(n):
    @app.task
    def work(x):
        return n*x
    return work
first=factory(2)
try:
    factory(3)
except AlreadyRegistered:
    print('decorator collision rejected')
else:
    raise AssertionError('collision was not rejected')

class One(app.Task):
    name='duplicate'
    def run(self, x): return x
class Two(app.Task):
    name='duplicate'
    def run(self, x): return x
app.register_task(One())
try:
    app.register_task(Two())
except AlreadyRegistered:
    print('class collision rejected')
else:
    raise AssertionError('class collision was not rejected')
PY"}

